// Per-frame check of a linked object's state; runs the handler or clears its flag.
int volume_camera_swing_check(char *m) {
    struct UpdateCamSwing *swing_camera_record = (struct UpdateCamSwing *)m;
    struct CamSwingParams *params =
        ((struct CamDescriptorRow *)camera_descriptors)[swing_camera_record->descriptor_index].params;
    short k;
    if (params->l_buttons_end == 1 && params->done != 0)
        return 0;
    if (params->type.s == 11 && hero_vehicle_mode != 2)
        return 0;
    k = params->type.u;
    if (k == 1 || k == 10) {
        if (params->timer == 0) {
            struct Hero *hero_data = (struct Hero *)g_hero;
            if (hero_data->frames_off_ground.s != 0) {
                if (*(int *)&g_current_level_index != LEVEL_OLTANIS)
                    return 0;
                if (hero_data->unk2284 != 13)
                    return 0;
            }
        }
    }
    if ((short)params->type.u == 2 && *(int *)(&hero_control_mode) != 0x1A) {
        params->timer = 0;
    } else {
        volume_camera_swing(m);
    }
    return 0;
}

