/* Returns nonzero when an object's path is blocked; otherwise marks the path entry as reached. */
int volume_camera_aim_active(void *arg) {
    struct VolAimCam *aim_camera_record = arg;
    struct VolAimCam *rec = (struct VolAimCam *)g_current_follow_cam;
    struct VolAimParams *params = ((struct VolAimDesc *)camera_descriptors)[aim_camera_record->descriptor_index].params;
    struct VolAimState *state = rec->saved_state;
    struct VolAimTail *tail = &state->tail;
    struct VolAimCtl *ctl = &state->tail.ctl;
    if (rec->unk86 != 0)
        return 0;
    if (params->only_in_mode_1 != 0 && ((struct VolAimWorld *)hero_globals_base)->mode != 1)
        return 0;
    if (params->not_in_mode_1 != 0 && ((struct VolAimWorld *)hero_globals_base)->mode == 1)
        return 0;
    if (params->need_still != 0) {
        float c = 0.01f;
        if (FastAbsF(tail->unk164) > c)
            return 0;
        if (FastAbsF(ctl->unk1B0) > c)
            return 0;
    }
    if (params->clip_volume >= 0) {
        if (is_point_inside_clip_volume((char *)&gHeroPos, params->clip_volume) != 0)
            return 1;
    }
    if (params->volume_25fa38 >= 0) {
        if (test_point_in_transformed_unit_cylinder((char *)&gHeroPos, params->volume_25fa38) != 0)
            return 1;
    }
    if (params->volume_25faf0 >= 0) {
        if (test_point_in_transformed_unit_sphere((float *)(&gHeroPos), params->volume_25faf0) != 0)
            return 1;
    }
    params->done = 1;
    return 0;
}
