/* Aim-camera update. */
void volume_camera_aim(void *cam_) {
    struct UpdateCam_ee *aim_camera_record = cam_;
    CameraVec_ee pos;
    CameraVec_ee to_pos;
    CameraVec_ee gravity_offset;
    CameraVec_ee level;
    AimCameraParams_ee *params;
    struct UpdateCam_ee *rec;
    float (*rec_pos)[4];
    FollowCamState_ee *rig;
    FollowCamState_ee *state;
    FollowCamBlock_ee *follow;
    FollowCamTail_ee *tail;
    FollowCamSnap_ee *snap;
    FollowCamReset_ee *reset;
    f32 up;
    f32 angle;

    params = ((CameraDescriptor_ee *)camera_descriptors)[aim_camera_record->descriptor_index].params;
    if (volume_camera_aim_active(aim_camera_record)) {
        if (try_select_follow_camera_volume(aim_camera_record) <= 0) {
            if (params->timer) {
                params->done = 1;
            }
            params->timer = 0;
            return;
        }
        if (!(pad_held & (PAD_L2 | PAD_L1))) {
            goto run;
        }
    }
    if (params->timer) {
        params->done = 1;
    }
    params->timer = 0;
    clear_follow_camera_volume_if_current(aim_camera_record);
    return;
run:
    if (params->timer < 2) {
        {
            pos[0] = ((CameraDescriptor_ee *)camera_descriptors)[aim_camera_record->descriptor_index].pos[0];
            pos[1] = ((CameraDescriptor_ee *)camera_descriptors)[aim_camera_record->descriptor_index].pos[1];
            pos[2] = ((CameraDescriptor_ee *)camera_descriptors)[aim_camera_record->descriptor_index].pos[2];
        }
        *(s32 *)&pos[3] = 0;
        FastVecSub(to_pos, pos, &(*(HeroLike_ee *)g_hero).motion.pos);
        up = FastVecDot(to_pos, (*(HeroLike_ee *)g_hero).gravity_dir);
        FastVecScale(gravity_offset, (*(HeroLike_ee *)g_hero).gravity_dir, up);
        FastVecSub(level, to_pos, gravity_offset);
        params->distance = FastVecLength(level);
        params->height = -up;
        angle = params->angle;
        if (FastAbsF(angle) == 1.5707964f) {
            *(s32 *)&params->offset_scale = 0;
        } else {
            params->offset_scale = params->height - params->distance * (FastSin(angle) / FastCos(angle));
        }
        rec = (struct UpdateCam_ee *)g_current_follow_cam;
        rig = (FollowCamState_ee *)rec->saved_state;
        rec_pos = &rec->pos;
        follow = &rig->follow;
        tail = &rig->tail;
        snap = &rig->tail.snap;
        state = rig;
        reset = &state->reset;
        qcopy(rec_pos, pos);
        tail->unk15C = params->distance;
        tail->distance = params->height;
        follow->look_height = params->offset_scale;
        FastVecScale(gravity_offset, (*(HeroLike_ee *)g_hero).gravity_dir, -tail->distance);
        FastVecAdd(state->follow.eye, &(*(HeroLike_ee *)g_hero).motion.pos, gravity_offset);
        FastVecSub(tail->unk130, pos, state->follow.eye);
        qcopy(state->tail.unk140, tail->unk130);
        FastVecScale(gravity_offset, (*(HeroLike_ee *)g_hero).gravity_dir, -follow->look_height);
        FastVecAdd(state->follow.look_target, &(*(HeroLike_ee *)g_hero).motion.pos, gravity_offset);
        qcopy(state->follow.unkD0, state->follow.look_target);
        qcopy(follow->focus, &(*(HeroLike_ee *)g_hero).motion.pos);
        qcopy(state->follow.offset, follow->focus);
        qcopy(state->position, rec_pos);
        qcopy(state->tail.snap.unk1F0, rec_pos);
        *(s32 *)&snap->unk200 = 0;
        *(s32 *)&reset->unk34 = 0;
        reset->look_height = follow->look_height;
        {
            f32 zero = reset->unk34;
            f32 distance = tail->distance;
            reset->distance = distance;
            reset->unk22 = 0;
            reset->unk38 = zero;
            reset->unk30 = zero;
            reset->unk2C = zero;
        }
    }
    params->timer += 1;
    if (scale_ticks(200) < params->timer) {
        params->timer = scale_ticks(200);
    }
    if (params->distance != 0.0f) {
        Cam_SetDistanceGoal_v(0, params->distance, 0.003f);
        set_follow_camera_flag_226();
    }
    if (params->height != 0.0f) {
        follow_camera_set_height(params->height, 0.003f);
    }
    if (params->offset_scale != 0.0f) {
        Cam_SetEyeOffset(0, params->offset_scale, 0.005f);
    }
    if (params->unk28 != 0.0f) {
        set_follow_camera_angle_1cc(params->unk28 * 0.017453292f);
    }
    if (params->keep_unk10 == 0) {
        set_follow_camera_orbit_clamp_mode(0);
    }
}
